from pathlib import Path
import textwrap
import nbformat as nbf

ROOT = Path(__file__).resolve().parents[1]
cells = []


def md(text):
    cells.append(nbf.v4.new_markdown_cell(textwrap.dedent(text).strip()))


def code(text):
    cells.append(nbf.v4.new_code_cell(textwrap.dedent(text).strip()))


md('# Чекпойнт 2. Анализ PlantVillage и PlantDoc\n\nПосмотрим, как устроены оба датасета, сколько в них классов, какие есть ошибки и повторы, чем отличаются фотографии. По результатам подготовим данные для обучения и проверки модели.')

md('## 1. Подготовка данных\n\nИспользуем два готовых датасета: PlantVillage и PlantDoc. В них фотографии уже разложены по папкам с названиями классов. Например, в PlantVillage папка `Tomato___healthy` содержит снимки здоровых листьев томата. По названию папки код определяет, к какому классу относится каждый снимок.\n\nСначала проверим, все ли изображения открываются, каких они размеров и сколько примеров есть в каждом классе. Затем найдем повторы и подготовим списки изображений для обучения и проверки модели.')

code("from pathlib import Path\nimport os, sys, json, hashlib, platform\nROOT = Path.cwd()\nassert (ROOT / 'scripts/eda_core.py').exists(), 'Запустите ноутбук из корня проекта'\nos.environ['MPLCONFIGDIR'] = str(ROOT / 'tmp/mpl')\nsys.path.insert(0, str(ROOT / 'scripts'))\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom IPython.display import display, Markdown\nfrom eda_core import build_metadata, validate_splits, PD_MAP, AMBIGUOUS, SEED, numeric_columns\nimport eda_figures as plots\nfrom embeddings import run as run_embeddings\nplots.style()\npd.set_option('display.max_colwidth', 80)\npd.set_option('display.max_rows', 45)\nREBUILD_METADATA = False\nREBUILD_EMBEDDINGS = False\nprint('Python:', platform.python_version(), '| seed:', SEED)")

md('<a id="data"></a>\n## 2. Датасеты\n\n**PlantVillage** содержит фотографии здоровых и больных листьев. Используем цветную версию `color` с [Hugging Face авторов](https://huggingface.co/datasets/mohanty/PlantVillage). Версии `grayscale` и `segmented` получены из тех же снимков, поэтому мы не добавляем их как новые примеры.\n\n**PlantDoc** берем из [этого репозитория для классификации](https://github.com/pratikkayal/PlantDoc-Dataset). Используем готовые папки train и test из репозитория авторов. Анализируем именно эти файлы: их количество и состав могут отличаться от других сборок PlantDoc.\n\nВ этих версиях 54 305 изображений PlantVillage и 2 572 PlantDoc. Дальше считаем статистики по фактически загруженным файлам.')

code("sources = json.loads((ROOT / 'data/external/sources.json').read_text())\ndisplay(pd.DataFrame(sources).T[['revision', 'license', 'extracted_files']])\ndf, pairs = build_metadata(force=REBUILD_METADATA)\ndf = numeric_columns(df)\nvalid = df[df.error.eq('')].copy()\nclean = df[df.split.ne('excluded')].copy()\noverview = df.groupby('dataset').agg(images=('image_id','size'), classes=('label','nunique'),\n                                      decoded=('error',lambda x: x.eq('').sum()))\noverview['usable_after_cleaning'] = clean.groupby('dataset').size()\ndisplay(overview)\nassert overview.loc['plantvillage','images'] == 54305\nassert overview.loc['plantdoc','images'] == 2572")

md('### 2.1. Баланс классов\n\nКласс задает и культуру, и состояние листа. Например, здоровые листья томата и яблони относятся к разным классам. Ниже посмотрим число снимков в каждом классе и отношение самого большого класса к самому маленькому.')

code("counts = df.groupby(['dataset','label']).size().rename('n').reset_index()\nimbalance = counts.groupby('dataset').n.agg(['min','median','max'])\nimbalance['max/min'] = imbalance['max'] / imbalance['min']\nimbalance['largest_class_share_%'] = 100 * imbalance['max'] / overview.images\ndisplay(imbalance.round(2))\ncounts.to_csv(ROOT / 'reports/class_counts.csv', index=False)\nplots.class_counts(df)")

md('В PlantVillage на класс приходится от 152 до 5 507 снимков, разница в 36.2 раза. В PlantDoc разброс еще больше: от 2 до 191, то есть в 95.5 раза. При таком дисбалансе высокая accuracy может скрывать ошибки на редких классах. На следующем этапе мб стоит обсудить macro-F1 и отдельно смотреть recall каждого класса.\n\nУ `Tomato two spotted spider mites leaf` всего 2 изображения, оба в исходном train. Проверить качество на этом классе в PlantDoc test не получится. Пока сохраняем все доступные обучающие примеры, взвешенную функцию потерь и сэмплинг мы сравним позже.')

md('### 2.2. Соответствие классов\n\nНазвания в датасетах отличаются, поэтому составим таблицу соответствий. Исходные названия тоже сохраняем.\n\nЧетыре метки слишком общие: `Apple rust leaf`, `Bell_pepper leaf spot`, `Corn leaf blight`, `Tomato leaf yellow virus`. Для них указали возможные соответствия, но в основное сравнение не включили. Остальные классы сопоставлены по названиям.\n\nВ папках PlantDoc здоровые листья названы без слова healthy, например `Apple leaf` и `Tomato leaf`. В [статье авторов, рисунок 2](https://arxiv.org/pdf/1911.10317), соответствующие классы указаны как Apple Healthy и Tomato Healthy. Поэтому сопоставляем их с классами здоровых листьев той же культуры в PlantVillage.')

code("mapping = df[df.dataset.eq('plantdoc')].groupby(['label','canonical_label','mapping_status']).agg(\n    raw_n=('image_id','size'), retained_n=('split',lambda s:s.ne('excluded').sum()),\n    field_test_n=('split',lambda s:s.eq('field_test').sum()), primary=('common_primary','max')).reset_index()\nmapping['note'] = mapping.label.map(AMBIGUOUS).fillna('')\nmapping.to_csv(ROOT / 'reports/class_mapping.csv', index=False)\ndisplay(mapping[['label','canonical_label','mapping_status','raw_n','field_test_n','primary']])\ncommon_labels = sorted(clean.loc[clean.common_primary, 'canonical_label'].unique())\nprint('Основное сравнение:', len(common_labels), 'класса')\n_ = (ROOT / 'splits/common_classes.json').write_text(json.dumps(common_labels, ensure_ascii=False, indent=2))")

md('<a id="quality"></a>\n## 3. Форматы, размеры и ошибки\n\nПроверяем каждый файл через `PIL.Image.verify()` и `.load()`: открывается ли он, есть ли метка, какой у него размер и цветовой режим. Перед расчетом признаков учитываем EXIF-ориентацию и приводим изображение к RGB. Исходные файлы сохраняем без изменений.')

code("quality = df.groupby('dataset').agg(\n    decode_errors=('error',lambda x:x.ne('').sum()),\n    missing_labels=('label',lambda x:x.eq('').sum()),\n    missing_mapping=('canonical_label',lambda x:x.eq('').sum()),\n    non_RGB=('mode',lambda x:x.ne('RGB').sum()),\n    zero_size=('bytes',lambda x:x.le(0).sum()))\ndisplay(quality)\ndisplay(pd.crosstab(df.dataset, [df['format'], df['mode']]))\ndisplay(valid.groupby('dataset')[['width','height','aspect_ratio']].agg(['min','median','max']).round(2))\ndisplay(valid[['width','height','bytes','brightness','saturation','sharpness']].describe().round(4))\nquality.to_csv(ROOT / 'reports/data_quality.csv')\nplots.dimension_plots(valid)")

md('Все файлы открылись, пустых меток нет. У PlantVillage есть один снимок в RGBA, у PlantDoc встречаются CMYK, grayscale и RGBA. Поэтому перед подачей в модель нужно приводить изображения к RGB.\n\nУ всех фото PlantVillage размер 256×256. У PlantDoc ширина меняется от 115 до 6 000 пикселей, высота от 69 до 6 000, медианы 800 и 667. Их придется приводить к одному размеру, сохраняя пропорции. При обрезке важно не потерять пораженную часть листа.(!)\n\nДля разбиения также нужна инфа о том, какие фотографии показывают один лист. Авторский `leaf_id` нашелся для 40 490 снимков PlantVillage. Для остальных 13 815 использован идентификатор из имени файла. В PlantDoc сведений о растениях и фотосессиях нет. Поэтому полностью исключить попадание связанных снимков в разные части датасета не получится.')

code("display(df.groupby(['dataset','leaf_id_source']).size().rename('n').to_frame())\n# Domain-specific outliers: fixed diagnostic flags, not automatic deletion.\nflags = valid.assign(low_resolution=valid[['width','height']].min(axis=1).lt(128),\n                     extreme_aspect=(valid.aspect_ratio.lt(.25)|valid.aspect_ratio.gt(4)),\n                     extreme_brightness=(valid.brightness.lt(.10)|valid.brightness.gt(.90)))\ndisplay(flags.groupby('dataset')[['low_resolution','extreme_aspect','extreme_brightness']].sum())\nflagged = flags[flags[['low_resolution','extreme_aspect','extreme_brightness']].any(axis=1)]\nflagged[['image_id','path','dataset','label','low_resolution','extreme_aspect','extreme_brightness']].to_csv(\n    ROOT / 'reports/quality_flags.csv', index=False)\nreviewed_extremes = plots.quality_gallery(valid)")

md('В таблице выше посчитали изображения маленького размера, с сильно вытянутыми пропорциями и очень низкой или высокой яркостью. Список этих фото сохранили в reports/quality_flags.csv. Вообще эти признаки сами по себе не считаем основанием для удаления.\n\n### 3.1. Примеры каждого класса\n\nВыберем по два снимка на класс с фиксированным seed. Этого по идее достаточно, чтобы увидеть характерные объекты и фон, но не чтобы проверить всю разметку)')

code('plots.class_galleries(df)')

md('В PlantVillage обычно виден один лист на простом фоне. В PlantDoc встречаются ветви, плоды, несколько листьев, надписи, коллажи и водяные знаки. На таких фотографиях модели сложнее понять, к какому объекту относится метка. Она также может запомнить фон или оформление вместо признаков болезни.')

md('<a id="duplicates"></a>\n## 4. Дубликаты и почти-дубликаты\n\nТочные копии определяем по хешам файлов и RGB-пикселей с учетом размера изображения. Для поиска похожих фото используем 64-битный pHash и BK-tree. Расстояние Хэмминга показывает, сколько битов различается у двух хешей; рассматриваем пары с расстоянием до 6.\n\nДля каждой пары также считаем среднее абсолютное отличие RGB после уменьшения изображений до 64×64. Значения каналов приводим к диапазону от 0 до 1. Почти-дубликатами считаем пары, которые проходят оба порога.\n\nПороги подбираем кодом по авторским `leaf_id` PlantVillage. Одинаковый идентификатор означает один лист. Он помогает проверить, не объединяет ли правило разные листья, но сам по себе не доказывает, что два снимка являются копиями.\n\nПо `leaf_id` и seed=42 делим листья примерно 70/30 на подбор и проверку. Пару используем, только если оба листа попали в одну часть. Это отдельное техническое разбиение: один лист не может участвовать одновременно в подборе и проверке порогов.\n\nПеребираем Хэмминг 0/2/4/6 и RGB от 0.005 до 0.15 с шагом 0.005. На части для подбора выбираем вариант, который находит больше пар одного листа и не объединяет разные листья. При равенстве выбираем меньший порог Хэмминга, затем RGB.')

code('from duplicate_audit import calibrate\n\ncalibration, calibration_grid = calibrate(df, pairs)\n# Показываем лучшие варианты без ошибок по авторским leaf_id на части для подбора.\ndisplay(calibration_grid.query(\'fp == 0 and tp > 0\')\n        .sort_values([\'tp\', \'hamming_max\', \'rgb_mae_max\'], ascending=[False, True, True])\n        .head(8).rename(columns={\'hamming_max\': \'Хэмминг\', \'rgb_mae_max\': \'RGB\',\n                                \'tp\': \'Пары одного листа\', \'fp\': \'Разные листья\',\n                                \'fn\': \'Не отобранные пары одного листа\', \'tn\': \'Отсеянные разные листья\'}))\ndisplay(pd.DataFrame({part: calibration[part] for part in [\'fit\', \'holdout\']}).T\n        .rename(index={\'fit\': \'Подбор\', \'holdout\': \'Проверка\'},\n                columns={\'tp\': \'Пары одного листа\', \'fp\': \'Разные листья\',\n                         \'fn\': \'Не отобранные пары одного листа\', \'tn\': \'Отсеянные разные листья\'}))\nassert calibration[\'holdout\'][\'fp\'] == 0\nselected_hamming = calibration[\'hamming_max\']\nselected_rgb = calibration[\'rgb_mae_max\']\ndisplay(Markdown(f\'Код выбрал пороги: **Хэмминг ≤ {selected_hamming}, RGB ≤ {selected_rgb:.3f}**. \'\n                 f\'Им соответствуют **{calibration["candidate_count"]} пар** без точных копий.\'))')

md('Получились пороги **Хэмминг ≤ 6 и RGB ≤ 0.035**. При подборе они выделили 17 пар с одинаковым `leaf_id`, на отдельной проверочной части 10. Пар с разными `leaf_id` в обоих случаях было 0. Таблица перебора сохранена в `reports/duplicate_calibration_grid.csv`.\n\nНиже показаны две пары, которые код считает почти-дубликатами: обе проходят пороги Хэмминга и RGB. Все расчеты по найденным парам сохранены в `reports/duplicate_rule_results.csv`.')

code("from PIL import Image, ImageOps\n\nimage_paths = valid.set_index('image_id')['path']\nexamples = pairs[pairs.near_duplicate].sort_values(\n    ['distance', 'rgb_mae', 'left_id', 'right_id']).head(2)\nassert len(examples) == 2\nassert examples.distance.le(selected_hamming).all() and examples.rgb_mae.le(selected_rgb).all()\nfig, axes = plt.subplots(2, 2, figsize=(10, 7))\nfor row, (_, pair) in enumerate(examples.iterrows()):\n    for col, key in enumerate(['left_id', 'right_id']):\n        with Image.open(ROOT / image_paths.loc[pair[key]]) as image:\n            axes[row, col].imshow(ImageOps.exif_transpose(image).convert('RGB'))\n        axes[row, col].axis('off')\n    axes[row, 0].set_title(f'Почти-дубликаты: пара {row + 1}', loc='left', fontsize=10)\n    axes[row, 1].set_title(f'Хэмминг: {pair.distance}; RGB: {pair.rgb_mae:.6f}', loc='left', fontsize=10)\nfig.tight_layout()\nfig.savefig(ROOT / 'reports/figures/duplicate_threshold_examples.png', dpi=150)\nplt.show()")

md('1. **Находим точные копии и почти-дубликаты.** Используем совпадение SHA-256 файлов или пикселей либо одновременное выполнение порогов pHash и RGB.\n2. **Объединяем найденные пары в группы.** Если A совпадает с B, а B с C, все три файла входят в одну группу.\n3. **В группе оставляем один файл.** Приоритет: PlantDoc test, PlantDoc train, PlantVillage. Внутри каждого набора выбираем по пути файла в алфавитном порядке. Если у файлов разные метки классов, исключаем всю группу.\n4. **Учитываем группы при разбиении.** Найденные повторы и снимки с одинаковым `leaf_id` остаются в одной части выборки.')

code("sensitivity = pd.DataFrame({'Hamming radius':[0,2,4,6],\n                            'candidate_pairs':[int(pairs.distance.le(r).sum()) for r in [0,2,4,6]]})\ndisplay(sensitivity)\ndisplay(pairs.groupby(['exact_pixels','remove_candidate']).size().rename('pairs').to_frame())\nbyte_counts = valid.groupby(['dataset','sha256']).size().groupby(level=0).apply(lambda s:int((s-1).clip(lower=0).sum()))\nprint('Лишние побайтовые копии внутри источников:', byte_counts.to_dict())\nprint('Пар между датасетами (pHash ≤6):', int(pairs.cross_dataset.sum()))\nprint('Из них проходят полное правило удаления:', int((pairs.cross_dataset & pairs.remove_candidate).sum()))\nremovals = df[df.exclusion_reason.ne('')].groupby(['dataset','exclusion_reason']).size().rename('images')\ndisplay(removals.to_frame())\ndf[df.exclusion_reason.ne('')][['image_id','path','label','exclusion_reason','duplicate_of','duplicate_group']].to_csv(\n    ROOT / 'reports/exclusions.csv', index=False)\nsensitivity.to_csv(ROOT / 'reports/phash_sensitivity.csv', index=False)\nplots.pair_gallery(df, pairs, 'near')\nplots.pair_gallery(df, pairs, 'conflict')")

md('По автоматическому правилу исключили 69 повторных фото PlantVillage и 33 PlantDoc. Еще в PlantDoc исключили 60 фото из групп с противоречивыми метками. Например, снимки одной группы встретились в классах `Corn leaf blight` и `Corn Gray leaf spot`.\n\nВсего исключили 162 изображения. Причины записаны в `reports/exclusions.csv` и `splits/manifest.csv`. Исходные файлы сохранены.')

md('<a id="conditions"></a>\n## 5. Фон, освещение и цвет\n\nСравним несколько характеристик изображений:\n\n- яркость: среднее `0.299R + 0.587G + 0.114B`;\n- насыщенность: среднюю S в HSV;\n- резкость: дисперсию лапласиана яркости после уменьшения до 128×128;\n- края изображения: внешние 13 пикселей с каждой стороны на размере 128×128.\n\nПо краям грубо оцениваем фон. Туда может попасть и лист, поэтому эта оценка не заменяет маску листа. Яркость здесь описывает само изображение,  не освещенность при съемке.')

code("metrics = ['brightness','saturation','contrast','sharpness','border_brightness','border_std']\ndisplay(valid.groupby('dataset')[metrics].agg(['median','mean']).round(4))\nplots.shooting_conditions(valid)\nplots.paired_domains(df)")

md('Даже при одинаковой метке сцены сильно отличаются. В PlantVillage это отдельные листья, а в PlantDoc также видны яблоки, ветви, земля и подписи. Разница не сводится к освещению.\n\nНа общие статистики влияет и состав классов. Чтобы уменьшить это влияние, ниже берем только общие классы: сначала считаем среднее внутри каждого класса и датасета, затем усредняем классы с одинаковым весом.')

code("matched = clean[clean.common_primary].groupby(['dataset','canonical_label'])[metrics].mean()\ndisplay(matched.groupby('dataset').mean().round(4))\nmatched.to_csv(ROOT / 'reports/conditions_by_common_class.csv')\nplots.color_by_class(valid)\n# Fraction of between-class variance in a feature, descriptive eta squared.\ndef eta_squared(group, feature):\n    x = group[feature].astype(float)\n    denominator = ((x-x.mean())**2).sum()\n    if denominator == 0:\n        return np.nan\n    stats = group.groupby('label')[feature].agg(['mean','size'])\n    return float((stats['size']*(stats['mean']-x.mean())**2).sum()/denominator)\neta = pd.DataFrame({ds:{feature:eta_squared(g,feature) for feature in ['brightness','border_brightness','mean_g']}\n                    for ds,g in valid.groupby('dataset')}).T\ndisplay(eta.round(3))")

md('Медианная яркость близка: 0.470 у PlantVillage и 0.476 у PlantDoc. При этом медианная насыщенность составляет 0.253 и 0.395, а разброс яркости краев 0.114 и 0.176. Разница насыщенности сохраняется и при одинаковом весе общих классов: средние равны 0.244 и 0.408. Значит, одного изменения яркости для сближения датасетов вряд ли хватит.\n\nЦвет и яркость краев различаются между классами. Это возможная подсказка для модели: она может запоминать фон вместо болезни. Пока это гипотеза, ведь в измерения попадает и сам лист. Позже проверим ее с помощью обрезки, замены фона и Grad-CAM с маской листа.')

md('<a id="augmentations"></a>\n## 6. Проверка аугментаций\n\nПосмотрим, как преобразования меняют снимки из train и field_dev. Отражения, небольшие повороты и умеренные изменения яркости выглядят правдоподобно, пока симптомы остаются видны. С обрезкой и изменением оттенка нужно осторожнее: можно убрать пораженный участок или изменить характерный цвет болезни.')

code('plots.augmentation_gallery(df)')

md('| Преобразование | Что попробуем при обучении | На что обратить внимание |\n|---|---|---|\n| Отражение по горизонтали, p=0.5 | Включить в первый набор аугментаций | На снимках бывают надписи |\n| Поворот до ±15° | Начать с небольших углов | Заполнять края отражением, чтобы не создавать черные углы |\n| Яркость/контраст ±15%, насыщенность ±10%, оттенок ±0.02 | Начать с этих мягких настроек | Цвет и контраст симптомов должны сохраняться |\n| RandomResizedCrop, площадь 0.85-1.0 | Проверить на примерах перед обучением | Обрезка может убрать больной участок |\n| Сильное изменение оттенка и большая обрезка | Пока не использовать | На примерах теряется цвет или видимость симптомов |\n| RandAugment, MixUp/CutMix, замена фона | Сравнить отдельно на чекпоинте 5 | Проверять пользу на validation |\n\nЗдесь проверили только внешний вид преобразований. Помогают ли они модели, станет понятно после обучения. Случайные аугментации будем применять к train; для val и test оставим фиксированную обработку. В примере поворота холст расширен, поэтому видны пустые углы.')

md('<a id="embeddings"></a>\n## 7. Признаки ResNet18 и t-SNE\n\nВозьмем ResNet18 с весами ImageNet-1K V1 и уберем последний слой. Для каждого снимка получим 512 чисел, описывающих его признаки. Сеть не дообучаем.\n\nПеред подачей в сеть уменьшаем короткую сторону до 256, вырезаем центр 224×224 и применяем нормализацию ImageNet. У PlantDoc такая обрезка иногда может убрать часть объекта. (Это стандартная обработка для выбранных предобученных весов ResNet18. Мы берем ее готовой через ResNet18_Weights.IMAGENET1K_V1.transforms())\n\nДля отдельных карт выбираем до 60 разных групп снимков на класс из PlantVillage train и PlantDoc field_dev. Для общей карты берем до 40 на класс из каждого датасета, с одинаковым числом снимков в каждой паре.\n\nПризнаки нормируем по L2, сокращаем до 50 компонент с PCA (50 взяли как типичное стартовое значение из рекомендации scikit-learn), затем строим t-SNE: `perplexity=30`, 1000 итераций, `seed=42`. Точки и параметры сохраняем. На картах классов выделяем по одному классу, чтобы не смешивать десятки цветов на одном графике.\n\nДополнительно считаем silhouette по исходным 512 признакам ResNet18: он сравнивает близость снимков внутри своего класса и к ближайшему другому классу. Это численная оценка разделения классов в дополнение к графикам t-SNE. На общей выборке также считаем silhouette по источнику снимков, чтобы оценить разделение PlantVillage и PlantDoc.')

code("points = run_embeddings(force=REBUILD_EMBEDDINGS)\nembedding_meta = json.loads((ROOT / 'data/processed/embedding_metadata.json').read_text())\nembedding_table = pd.DataFrame(embedding_meta['metrics']).T\ndisplay(embedding_table.style.format({'n':'{:.0f}', 'classes':'{:.0f}',\n    'class_silhouette_cosine_512d':'{:.4f}', 'domain_silhouette_cosine_512d':'{:.4f}'}, na_rep='—'))\nplots.embedding_plots(points)")

md('На отдельных графиках t-SNE смотрим, собираются ли фото одного класса вместе: в PlantVillage некоторые классы хорошо выделяются, в PlantDoc многие смешиваются с другими.\n\nНа общем графике снимки заметно разделяются по датасетам даже при одинаковом составе классов: готовая ResNet18 видит разницу между источниками.\n\nПоэтому будущую модель отдельно проверим на PlantDoc; сами графики точность классификации не показывают.')

code('values = embedding_meta[\'metrics\']\ndisplay(Markdown(\n    f"**Получено:** silhouette классов в исходных эмбеддингах "\n    f"PlantVillage = **{values[\'pv\'][\'class_silhouette_cosine_512d\']:.3f}**, "\n    f"PlantDoc = **{values[\'pd\'][\'class_silhouette_cosine_512d\']:.3f}**. "\n    f"На совместной сбалансированной выборке silhouette домена = "\n    f"**{values[\'joint\'][\'domain_silhouette_cosine_512d\']:.3f}**. "\n    "Показатели относятся только к указанным выборкам; это не результат обучения классификатора."))')

md('<a id="splits"></a>\n## 8. Разбиение данных\n\n**PlantVillage:** train/val/test примерно 70/15/15, `seed=42`. Используем `StratifiedGroupKFold`: 14 из 20 частей для train, по 3 для val и test. Снимки одного листа и повторы остаются вместе.\n\n**PlantDoc:** авторские train/test после очистки используем как `field_dev`/`field_test`. При пересечении групп приоритет у test. На `field_dev` подбираем улучшения, `field_test` сохраняем для итоговой оценки.\n\nАугментации применяем после разбиения, только к train.')

code("validate_splits(df, pairs)\nsplit_counts = pd.crosstab(df.dataset, df.split)\ndisplay(split_counts)\nsplit_counts.to_csv(ROOT / 'reports/split_counts.csv')\npv_class_split = pd.crosstab(clean.loc[clean.dataset.eq('plantvillage'),'label'],\n                             clean.loc[clean.dataset.eq('plantvillage'),'split'])\ndisplay(pv_class_split)\npv_class_split.to_csv(ROOT / 'reports/plantvillage_class_splits.csv')\nprimary_support = clean[clean.common_primary & clean.dataset.eq('plantdoc')].groupby('split').agg(\n    images=('image_id','size'), classes=('canonical_label','nunique'))\ndisplay(primary_support)\nprint('Проверки пройдены: группы листьев и установленных повторов не пересекают разбиения.')\nprint('Все 38 классов PlantVillage представлены в train, val и test.')\nmanifest_sha = hashlib.sha256((ROOT/'splits/manifest.csv').read_bytes()).hexdigest()\nprint('SHA-256 manifest:', manifest_sha)\nsplit_meta = {'seed':SEED, 'plantvillage_target_ratios':[.70,.15,.15],\n              'method':'StratifiedGroupKFold 20; folds 0:3 test, 3:6 val, 6:20 train',\n              'phash_search_radius':6, 'threshold_calibration':calibration,\n              'duplicate_decision_rule':'exact bytes/pixels OR (pHash Hamming <= 6 AND RGB MAE <= 0.035)',\n              'automatic_rule_sha256':hashlib.sha256((ROOT/'scripts/duplicate_audit.py').read_bytes()).hexdigest(),\n              'manifest_sha256':manifest_sha,\n              'common_classes':common_labels,\n              'limitation':'Leaf identity incomplete; rotated/cropped near-duplicates may remain.'}\n_ = (ROOT/'splits/metadata.json').write_text(json.dumps(split_meta,ensure_ascii=False,indent=2))")

md('### Как будем сравнивать модели\n\nНа чекпоинте 3 согласуем с куратором **macro-F1**: она дает каждому классу одинаковый вес, что важно при дисбалансе. Сравним качество на 23 общих классах PlantVillage test и PlantDoc field_test. Настройки подбираем на val/field_dev, тест оставляем для итоговой оценки.')

md('<a id="conclusions"></a>\n## 9. Итоги\n\n- Все изображения открываются. После очистки осталось **54 236 фото PlantVillage и 2 479 PlantDoc**.\n- Классы несбалансированы; для сравнения датасетов выделили **23 общих класса**.\n- Фон, цвет и условия съемки различаются. На t-SNE снимки разделяются по источнику, поэтому качество модели проверим отдельно на PlantDoc.\n- Сохранили разбиение с `seed=42`: PlantVillage примерно 70/15/15, PlantDoc по авторским train/test. Найденные повторы и группы одного листа остаются вместе.\n- Для первого обучения выбрали мягкие аугментации: сильная обрезка и изменение цвета могут скрыть симптомы.\n\nДальше согласуем метрику и обучим baseline. Практическое применение описано в [PDF](reports/practical_value.pdf).')

code("summary = {'raw_images':overview.images.to_dict(), 'usable_images':overview.usable_after_cleaning.to_dict(),\n           'raw_classes':overview.classes.to_dict(), 'common_classes':len(common_labels),\n           'exclusions':df[df.exclusion_reason.ne('')].exclusion_reason.value_counts().to_dict(),\n           'split_counts':split_counts.to_dict(), 'embedding_metrics':embedding_meta['metrics'],\n           'manifest_sha256':manifest_sha, 'seed':SEED}\n(ROOT/'reports/eda_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))\nassert sum(overview.images) == len(df)\nassert len(clean) + df.split.eq('excluded').sum() == len(df)\nassert len(common_labels) == 23")

